import { describe, it, expect } from "vitest";
import {
  sumWeeks,
  averageWeeks,
  seasonAdot,
  seasonPacr,
  seasonRacr,
  seasonYacPerRec,
  seasonCpoe,
  seasonPassingEpa,
  seasonRushingEpa,
  seasonReceivingEpa,
  ADVANCED_CONFIG,
} from "../stats.js";
import { STAT_GLOSSARY } from "../glossary.js";
import golden from "./golden-season-aggregates.json";

/**
 * Golden-contract test: stats.js and etl/percentiles.py implement the same
 * season-aggregation rules in two languages (JS for raw display values,
 * Python for percentile ranking). The golden file is generated by
 * etl/generate_golden.py — synthetic weeks in, Python-aggregated season
 * values out — and this suite asserts the JS helpers produce identical
 * numbers from the same weeks. If either side changes without the other,
 * this fails.
 *
 * Regenerate after contract changes:  cd etl && python generate_golden.py
 */

// metric name in the golden file → JS helper that must reproduce it
const JS_EQUIVALENTS = {
  passingEpa: (weeks) => seasonPassingEpa(weeks),
  pacr: (weeks) => seasonPacr(weeks),
  passingCpoe: (weeks) => seasonCpoe(weeks),
  passingAirYards: (weeks) => sumWeeks(weeks, "passingAirYards"),
  adot: (weeks) => seasonAdot(weeks),
  sacksSuffered: (weeks) => sumWeeks(weeks, "sacksSuffered"),
  // Magnitude, as ADVANCED_CONFIG displays it; nflverse stores it negative.
  sackYardsLost: (weeks) => Math.abs(sumWeeks(weeks, "sackYardsLost")),
  targetShare: (weeks) => averageWeeks(weeks, "targetShare"),
  airYardsShare: (weeks) => averageWeeks(weeks, "airYardsShare"),
  wopr: (weeks) => averageWeeks(weeks, "wopr"),
  racr: (weeks) => seasonRacr(weeks),
  receivingAirYards: (weeks) => sumWeeks(weeks, "receivingAirYards"),
  yacPerRec: (weeks) => seasonYacPerRec(weeks),
  receivingEpa: (weeks) => seasonReceivingEpa(weeks),
  rushingEpa: (weeks) => seasonRushingEpa(weeks),
  carries: (weeks) => sumWeeks(weeks, "carries"),
};

// Known, documented drift between the two implementations. Each entry is
// "<playerId>:<metric>". Its test is declared with it.fails, so the suite
// stays green while the bug exists and goes RED the moment the JS side is
// fixed — at which point the entry must be deleted. Never add an entry
// without a note explaining the discrepancy. Currently empty.
const KNOWN_DRIFT = new Set([]);

describe("stats.js mirrors the percentiles.py aggregation contract", () => {
  it("golden file covers every position the ETL ranks", () => {
    const positions = new Set(golden.players.map((p) => p.position));
    expect([...positions].sort()).toEqual(Object.keys(golden.positionConfigs).sort());
  });

  it("every ranked metric has a JS equivalent under test", () => {
    for (const config of Object.values(golden.positionConfigs)) {
      // Season-sourced metrics have no weekly rows; they live in advancedValues.
      const weekly = config.metrics.filter((m) => !config.seasonSourced.includes(m));
      for (const metric of weekly) {
        expect(JS_EQUIVALENTS, metric).toHaveProperty(metric);
      }
    }
  });

  for (const player of golden.players) {
    const expected = golden.expected[player.playerId];

    describe(`${player.playerId} (${player.position})`, () => {
      for (const [metric, expectedValue] of Object.entries(expected)) {
        const declare = KNOWN_DRIFT.has(`${player.playerId}:${metric}`) ? it.fails : it;
        declare(`${metric} matches the Python aggregation`, () => {
          const actual = JS_EQUIVALENTS[metric](player.weeks);

          if (expectedValue === null) {
            // Python null means "no basis to compute" (e.g. PACR with zero
            // air yards) — the JS ratio helpers must agree with null, not 0.
            expect(actual).toBeNull();
          } else {
            expect(actual).toBeCloseTo(expectedValue, 9);
          }
        });
      }
    });
  }
});

// Mirrors the Contract: groups in order of first appearance per position.
const EXPECTED_GROUPS = {
  QB: ["EFFICIENCY", "TRACKING · NEXT GEN", "PRESSURE", "EXPECTED POINTS", "BIG PLAYS & FUMBLES"],
  WR: ["USAGE", "EFFICIENCY", "TRACKING · NEXT GEN", "CHARTING · PFR", "EXPECTED POINTS", "BIG PLAYS & FUMBLES"],
  TE: ["USAGE", "EFFICIENCY", "TRACKING · NEXT GEN", "CHARTING · PFR", "EXPECTED POINTS", "BIG PLAYS & FUMBLES"],
  RB: ["EFFICIENCY", "USAGE", "TRACKING · NEXT GEN", "CHARTING · PFR", "EXPECTED POINTS", "BIG PLAYS & FUMBLES"],
};
const PFR_KEYS = [
  "pressureRate", "badThrowPct", "dropRate", "brokenTackles",
  "ratingWhenTargeted", "intsWhenTargeted", "beforeContactPerAtt", "afterContactPerAtt",
];
const STYLE_KEYS = ["timeToThrow", "aggressiveness", "airYardsToSticks", "cushion", "eightBoxPct", "timeToLos"];

describe("ADVANCED_CONFIG matches the ETL config", () => {
  for (const [pos, config] of Object.entries(golden.positionConfigs)) {
    const rows = ADVANCED_CONFIG[pos];

    describe(pos, () => {
      it("keys follow Python metric order", () => {
        expect(rows.map((r) => r.key)).toEqual(config.metrics);
      });

      it("lower direction is exactly the inverted set", () => {
        const lower = rows.filter((r) => r.direction === "lower").map((r) => r.key);
        expect([...lower].sort()).toEqual([...config.inverted].sort());
      });

      it("style direction is exactly the style set", () => {
        const style = rows.filter((r) => r.direction === "style").map((r) => r.key);
        expect(style.sort()).toEqual(STYLE_KEYS.filter((k) => config.metrics.includes(k)).sort());
      });

      it("every season-sourced row reads advancedValues", () => {
        for (const row of rows.filter((r) => config.seasonSourced.includes(r.key))) {
          expect(row.rawValue([], { advancedValues: { [row.key]: 1 } }), row.key).not.toBe("—");
          expect(row.rawValue([], {}), row.key).toBe("—");
        }
      });

      it("every label has a glossary entry", () => {
        for (const row of rows) expect(STAT_GLOSSARY, row.label).toHaveProperty([row.label]);
      });

      it("since is 2018 exactly on PFR rows", () => {
        for (const row of rows) {
          expect(row.since, row.key).toBe(PFR_KEYS.includes(row.key) ? 2018 : undefined);
        }
      });

      it("groups follow the contract order", () => {
        const seen = [];
        for (const r of rows) if (!seen.includes(r.group)) seen.push(r.group);
        expect(seen).toEqual(EXPECTED_GROUPS[pos]);
        // each group is one contiguous run
        expect(rows.map((r) => r.group).join("|").split("|").length).toBe(rows.length);
        const runs = rows.filter((r, i) => i === 0 || rows[i - 1].group !== r.group).length;
        expect(runs).toBe(EXPECTED_GROUPS[pos].length);
      });
    });
  }
});
